/* cell_temp.c — see cell_temp.h. */

#include "cell_temp.h"

/* Generated by App/bms/logic/gen_cell_temp.py: entry i is the temperature
   of a reading of CELL_TEMP_MV_MIN + i millivolts, in 0.1 C. */
extern const int16_t cell_temp_table[CELL_TEMP_MV_MAX - CELL_TEMP_MV_MIN + 1u];

bool cell_temp_from_mv(uint16_t mv, int16_t *deci_c)
{
    if (mv < CELL_TEMP_MV_MIN || mv > CELL_TEMP_MV_MAX) {
        return false;
    }
    *deci_c = cell_temp_table[mv - CELL_TEMP_MV_MIN];
    return true;
}
